package com.digiaudit.grcpc.modules.masterdata.coverage.requirementcontrol.api;

import com.digiaudit.grcpc.modules.masterdata.coverage.requirementcontrol.api.dto.CentralRequirementControlCoverageOptionsResponse; import com.digiaudit.grcpc.modules.masterdata.coverage.requirementcontrol.api.dto.CentralSubprocessRequirementControlCoverageResponse; import com.digiaudit.grcpc.modules.masterdata.coverage.requirementcontrol.application.CentralSubprocessRequirementControlCoverageQueryService; import com.digiaudit.grcpc.modules.masterdata.shared.domain.MasterDataLifecycleStatus; import java.util.List; import java.util.UUID; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/master-data/central")
public class CentralRequirementControlCoverageQueryController {
  private final CentralSubprocessRequirementControlCoverageQueryService queries; public CentralRequirementControlCoverageQueryController(CentralSubprocessRequirementControlCoverageQueryService queries){this.queries=queries;}
  @GetMapping("/subprocesses/{subprocessId}/requirement-control-coverages") @PreAuthorize("@masterDataAuthorization.canView('PROCESS') and @masterDataAuthorization.canView('GOVERNANCE') and @masterDataAuthorization.canView('CONTROL')") public List<CentralSubprocessRequirementControlCoverageResponse> list(@PathVariable UUID subprocessId,@RequestParam(required=false) MasterDataLifecycleStatus status,@RequestParam(required=false) String search){return queries.listForSubprocess(subprocessId,status,search);}
  @GetMapping("/subprocesses/{subprocessId}/requirement-control-coverages/deleted") @PreAuthorize("@masterDataAuthorization.canView('PROCESS') and @masterDataAuthorization.canView('GOVERNANCE') and @masterDataAuthorization.canView('CONTROL')") public List<CentralSubprocessRequirementControlCoverageResponse> deleted(@PathVariable UUID subprocessId,@RequestParam(required=false) String search){return queries.deleted(subprocessId,search);}
  @GetMapping("/subprocesses/{subprocessId}/requirement-control-coverages/options") @PreAuthorize("@masterDataAuthorization.canView('PROCESS') and @masterDataAuthorization.canView('GOVERNANCE') and @masterDataAuthorization.canView('CONTROL')") public CentralRequirementControlCoverageOptionsResponse options(@PathVariable UUID subprocessId){return queries.options(subprocessId);}
  @GetMapping("/subprocesses/{subprocessId}/requirement-control-coverages/{coverageId}") @PreAuthorize("@masterDataAuthorization.canView('PROCESS') and @masterDataAuthorization.canView('GOVERNANCE') and @masterDataAuthorization.canView('CONTROL')") public CentralSubprocessRequirementControlCoverageResponse detail(@PathVariable UUID subprocessId,@PathVariable UUID coverageId){return queries.detail(subprocessId,coverageId);}
  @GetMapping("/controls/{controlId}/requirement-coverages") @PreAuthorize("@masterDataAuthorization.canView('PROCESS') and @masterDataAuthorization.canView('GOVERNANCE') and @masterDataAuthorization.canView('CONTROL')") public List<CentralSubprocessRequirementControlCoverageResponse> forControl(@PathVariable UUID controlId,@RequestParam(required=false) String search){return queries.listForControl(controlId,search);}
  @GetMapping("/regulation-requirements/{requirementId}/control-coverages") @PreAuthorize("@masterDataAuthorization.canView('PROCESS') and @masterDataAuthorization.canView('GOVERNANCE') and @masterDataAuthorization.canView('CONTROL')") public List<CentralSubprocessRequirementControlCoverageResponse> forRequirement(@PathVariable UUID requirementId,@RequestParam(required=false) String search){return queries.listForRequirement(requirementId,search);}
}
